import{_ as t,C as n,o as r,c as l,j as a,a as s,E as i,ah as d}from"./chunks/framework.BpF7DVZ1.js";const x=JSON.parse('{"title":"后台壳","description":"","frontmatter":{},"headers":[],"relativePath":"examples/admin-shell.md","filePath":"examples/admin-shell.md","lastUpdated":1788635489000}'),m={name:"examples/admin-shell.md"};function c(h,e,p,f,_,u){const o=n("XhDemo");return r(),l("div",null,[e[0]||(e[0]=a("h1",{id:"后台壳",tabindex:"-1"},[s("后台壳 "),a("a",{class:"header-anchor",href:"#后台壳","aria-label":'Permalink to "后台壳"'},"​")],-1)),e[1]||(e[1]=a("p",null,"一副控制台外壳：头、侧栏、正文、脚四段各就各位，导航、面包屑、页头、工具条、通知角标与账户菜单在同一屏里。",-1)),i(o,{src:"examples/01-admin-shell"}),e[2]||(e[2]=d('<h2 id="这一屏定了什么" tabindex="-1">这一屏定了什么 <a class="header-anchor" href="#这一屏定了什么" aria-label="Permalink to &quot;这一屏定了什么&quot;">​</a></h2><ul><li><strong>骨架归<a href="./../components/layout">布局</a>，不归 CSS。</strong> 四段哪一段缺席就少一行或少一列，侧栏折叠改的是宽度不是可见性，折起来时侧栏里的滚动位置与输入值都还在。</li><li><strong>头部只有一条基线。</strong> 右半区整体推到行尾，中间那段留白由 <code>margin-inline-start: auto</code> 撑开；分隔线是<a href="./../components/separator">分隔线</a>组件，不是一段 <code>border</code>。</li><li><strong>导航状态落在叶子上。</strong> <a href="./../components/side-nav">侧栏导航</a>选中的是叶子节点，祖先枝跟着点亮；展开集合与选中值是两份状态，折叠不会把选中丢掉。</li><li><strong>一屏里只出现一种间距节奏。</strong> 头部、正文、卡片之间的空隙全部取自同一组间距令牌（<code>--xh-space-*</code>），圆角与描边同理；写死的像素只剩这一屏自己的高度与卡片的换行下限。</li><li><strong>颜色一处都不写死。</strong> 卡片描边、脚注文字、工具条底色都走<a href="./../guide/theme">设计令牌</a>，切深色模式时整屏一起翻面。</li></ul><h2 id="换成你的项目" tabindex="-1">换成你的项目 <a class="header-anchor" href="#换成你的项目" aria-label="Permalink to &quot;换成你的项目&quot;">​</a></h2><ul><li>侧栏与面包屑各自持有自己的数据，路由由你接：<code>href</code> 是你写的，组件不接管跳转。</li><li>账户菜单的触发器是插槽内容，换成头像、名字加箭头，或者别的什么都行——<a href="./../components/menu">菜单</a>只接管展开与键盘。</li><li>正文区那两张<a href="./../components/card">卡片</a>是占位，换成<a href="./../components/table">表格</a>、图表或<a href="./../components/empty-state">空态</a>都不影响外壳。</li></ul>',4))])}const b=t(m,[["render",c]]);export{x as __pageData,b as default};
